let data = msg.payload;

// --- Detectar sensor dañado ---
if (data === null || data.temperatura === undefined ||
    data.temperatura > 50 || data.temperatura < -80) {
    msg.sensor_estado = 'FALLA';
    msg.alerta_tipo   = 'SENSOR_DAÑADO';
    msg.alerta_msg    = '⛔ Congelador A: sensor sin señal o fuera de rango';
    msg.congelador    = 'A';
    return [null, msg];
}

// --- Evaluar temperatura ---
if (data.temperatura > -5) {
    data.estado = 'CRÍTICO';
} else if (data.temperatura > -18) {
    data.estado = 'ALERTA';
} else {
    data.estado = 'OK';
}

msg.temp          = data.temperatura;
msg.hum           = data.humedad;
msg.esp           = data.especie;
msg.tiempo        = data.tiempo_almacenamiento;
msg.estado        = data.estado;
msg.sensor_estado = 'OK';
msg.congelador    = 'A';

// Guardar temp actual en contexto global para regulación
global.set('temp_A', msg.temp);

// Generar alerta si no está en rango normal
if (data.estado !== 'OK') {
    msg.alerta_tipo = data.estado === 'CRÍTICO' ? 'TEMP_CRÍTICA' : 'TEMP_ELEVADA';
    msg.alerta_msg  = (data.estado === 'CRÍTICO' ? '🔴' : '🟠') +
        ' Congelador A: ' + msg.temp + '°C — ' + data.estado;
    return [msg, msg];
}

msg.alerta_tipo = 'OK';
msg.alerta_msg  = '';
return [msg, null];

