var cong      = msg.congelador || '?';
var tipo      = msg.alerta_tipo;
var texto     = msg.alerta_msg;
var keyUltima = 'ultima_alerta_' + cong;
var ultima    = global.get(keyUltima);

if (ultima !== tipo) {
    global.set(keyUltima, tipo);
    var hora = new Date().toTimeString().slice(0,8);
    var hist = global.get('notificaciones') || [];
    hist.unshift({ hora: hora, tipo: tipo, msg: texto, cong: cong });
    if (hist.length > 50) hist.pop();
    global.set('notificaciones', hist);
}

var hist = global.get('notificaciones') || [];

if (hist.length === 0) {
    msg.payload = '<div class="nw"><div class="nw-head">Notificaciones</div><div class="ne">Sin notificaciones registradas.</div></div>';
    return msg;
}

var html = '<div class="nw">';
html += '<div class="nw-head">Notificaciones del sistema</div>';
html += '<div class="nw-scroll"><table class="nt">';
html += '<thead><tr><th>Hora</th><th>Cong.</th><th>Estado</th><th>Mensaje</th></tr></thead><tbody>';

hist.forEach(function(n) {
    var badge = 'badge-normal', label = 'Normal';
    if      (n.tipo === 'TEMP_CRÍTICA')        { badge = 'badge-critica';  label = 'Crítica'; }
    else if (n.tipo === 'TEMP_ELEVADA')        { badge = 'badge-alerta';   label = 'Alerta'; }
    else if (n.tipo === 'SETPOINT')            { badge = 'badge-control';  label = 'Control'; }
    else if (n.tipo === 'SENSOR_DAÑADO')       { badge = 'badge-sensor';   label = 'Sensor'; }
    else if (n.tipo === 'SENSOR_DESCONECTADO') { badge = 'badge-sensor';   label = 'Desc.'; }
    else if (n.tipo === 'INTERNET_FALLA')      { badge = 'badge-internet'; label = 'Internet'; }
    else if (n.tipo === 'INTERNET_OK')         { badge = 'badge-normal';   label = 'Internet'; }

    html += '<tr class="nr">';
    html += '<td><span class="nh">' + n.hora + '</span></td>';
    html += '<td><span class="nc">' + n.cong + '</span></td>';
    html += '<td><span class="badge ' + badge + '">' + label + '</span></td>';
    html += '<td><span class="nm">' + n.msg + '</span></td>';
    html += '</tr>';
});

html += '</tbody></table></div></div>';
msg.payload = html;
return msg;

var setpoint   = msg.payload;
var congelador = msg.topic;   // 'A', 'B' o 'C'
var temp_actual = global.get('temp_' + congelador) || 0;

global.set('setpoint_' + congelador, setpoint);

var accion;
if (temp_actual > setpoint + 1) {
    accion = 'ENFRIAR';
} else if (temp_actual < setpoint - 1) {
    accion = 'CALENTAR';
} else {
    accion = 'MANTENER';
}

// Notificar el cambio de setpoint
var notifMsg = {
    alerta_tipo: 'SETPOINT',
    alerta_msg: '🎛 Congelador ' + congelador + ': setpoint ajustado a ' + setpoint + '°C — acción: ' + accion,
    congelador: congelador
};

// Publicar comando vía MQTT hacia el simulador.py
msg.payload = { congelador: congelador, setpoint: setpoint, accion: accion };
msg.topic   = 'pesquera/congelador/' + congelador + '/control';
node.send([msg, notifMsg]);
return null;

var cong  = msg.congelador;
var temp  = msg.temp;
var hum   = msg.hum;
var esp   = msg.esp;
var est   = msg.estado;

var estado = global.get('cuarto_estado') || { A: null, B: null, C: null };
estado[cong] = { temp: temp, hum: hum, esp: esp, estado: est, hora: new Date().toTimeString().slice(0,8) };
global.set('cuarto_estado', estado);

var critico = false;
var alerta  = false;
['A','B','C'].forEach(function(c) {
    if (!estado[c]) return;
    if (estado[c].estado === 'CRÍTICO') critico = true;
    if (estado[c].estado === 'ALERTA')  alerta  = true;
});

var s = critico ? 'critico' : alerta ? 'alerta' : 'ok';
var label = critico ? '🔴 CRÍTICO' : alerta ? '🟡 ALERTA' : '🟢 NORMAL';
var hora = new Date().toTimeString().slice(0,8);

var html = '<div class="cf">';

// Banner principal
html += '<div class="cf-banner cf-banner-' + s + '">';
html += '<div class="cf-dot cf-dot-' + s + '"></div>';
html += '<div class="cf-banner-inner">';
html += '<div class="cf-banner-lbl">Estado general del cuarto frío</div>';
html += '<div class="cf-banner-val cf-val-' + s + '">' + label + '</div>';
html += '</div>';
html += '<div class="cf-banner-time">' + hora + '</div>';
html += '</div>';

// Tarjetas
html += '<div class="cf-grid">';
['A','B','C'].forEach(function(c) {
    var d = estado[c];
    if (!d) {
        html += '<div class="cf-card cf-card-vacio">';
        html += '<div class="cf-card-head"><span class="cf-card-name">❄️ CONGELADOR ' + c + '</span></div>';
        html += '<div class="cf-empty">Sin datos aún…</div>';
        html += '</div>';
        return;
    }
    var cs = d.estado === 'CRÍTICO' ? 'critico' : d.estado === 'ALERTA' ? 'alerta' : 'ok';
    html += '<div class="cf-card cf-card-' + cs + '">';
    html += '<div class="cf-card-head">';
    html += '<span class="cf-card-name">❄️ CONG. ' + c + '</span>';
    html += '<span class="cf-bdg cf-bdg-' + cs + '">' + d.estado + '</span>';
    html += '</div>';
    html += '<div class="cf-temp cf-temp-' + cs + '">' + d.temp + ' °C</div>';
    html += '<div class="cf-meta">';
    html += '<div class="cf-row"><span class="cf-row-lbl">💧 Humedad</span><span class="cf-row-val">' + d.hum + '%</span></div>';
    html += '<div class="cf-row"><span class="cf-row-lbl">🐟 Especie</span><span class="cf-row-val">' + d.esp + '</span></div>';
    html += '</div>';
    html += '<div class="cf-hora">Actualizado: ' + d.hora + '</div>';
    html += '</div>';
});
html += '</div></div>';

msg.payload = html;
return msg;

var prev = global.get('internet_estado') || 'OK';
global.set('internet_estado', 'OK');

msg.internet = 'OK';
msg.internet_msg = '✅ Conexión a internet activa';
msg.internet_color = '#166534';
msg.internet_bg = '#dcfce7';

// Solo notificar si venía de falla
if (prev === 'FALLA') {
    var hist = global.get('notificaciones') || [];
    var hora = new Date().toTimeString().slice(0,8);
    hist.unshift({ hora: hora, tipo: 'INTERNET_OK', msg: '✅ Conexión a internet restaurada', cong: 'SYS' });
    global.set('notificaciones', hist);
}

return msg;

var prev = global.get('internet_estado') || 'OK';
global.set('internet_estado', 'FALLA');

msg.internet = 'FALLA';
msg.internet_msg = '❌ Sin conexión a internet';
msg.internet_color = '#b91c1c';
msg.internet_bg = '#fee2e2';

// Solo notificar si es nueva falla
if (prev !== 'FALLA') {
    var hist = global.get('notificaciones') || [];
    var hora = new Date().toTimeString().slice(0,8);
    hist.unshift({ hora: hora, tipo: 'INTERNET_FALLA', msg: '❌ Pérdida de conexión a internet detectada', cong: 'SYS' });
    global.set('notificaciones', hist);
    global.set('ultima_alerta_SYS', 'INTERNET_FALLA');
}

return msg;

var estado = msg.internet || global.get('internet_estado') || 'OK';
var hora   = new Date().toTimeString().slice(0,8);
var isOK   = estado === 'OK';
var s      = isOK ? 'ok' : 'falla';

var html = '<div class="inet">';
html += '<div class="inet-card inet-' + s + '">';
html += '<div class="inet-ico">' + (isOK ? '🌐' : '🔌') + '</div>';
html += '<div class="inet-info">';
html += '<div class="inet-lbl">Conectividad a internet</div>';
html += '<div class="inet-status inet-' + s + '-txt">' + (isOK ? 'Conexión activa' : 'Sin conexión a internet') + '</div>';
html += '<div class="inet-sub">Verificación cada 30 s · Última: ' + hora + '</div>';
html += '</div>';
html += '<div class="inet-dot inet-dot-' + s + '"></div>';
html += '</div></div>';

msg.payload = html;
return msg;

// Reconstruir tabla de notificaciones (reutiliza la lógica del generador)
var hist = global.get('notificaciones') || [];
if (hist.length === 0) { return null; }

var html = '<div class="notif-container"><table class="notif-table">';
html += '<thead><tr><th>Hora</th><th>Congelador</th><th>Estado</th><th>Mensaje</th></tr></thead><tbody>';

hist.forEach(function(n) {
    var badge = 'badge-normal';
    var textoEstado = 'Normal';
    if (n.tipo === 'TEMP_CRÍTICA' || n.tipo === 'INTERNET_FALLA' || n.tipo === 'SENSOR_DAÑADO') { badge = 'badge-critica'; textoEstado = n.tipo === 'INTERNET_FALLA' ? 'Internet' : 'Crítica'; }
    else if (n.tipo === 'TEMP_ELEVADA') { badge = 'badge-alerta'; textoEstado = 'Alerta'; }
    else if (n.tipo === 'SETPOINT') { badge = 'badge-control'; textoEstado = 'Control'; }
    else if (n.tipo === 'INTERNET_OK') { badge = 'badge-normal'; textoEstado = 'Internet'; }
    html += '<tr class="notif-row"><td>' + n.hora + '</td>';
    html += '<td><strong>' + n.cong + '</strong></td>';
    html += '<td><span class="badge ' + badge + '">' + textoEstado + '</span></td>';
    html += '<td>' + n.msg + '</td></tr>';
});
html += '</tbody></table></div>';
msg.payload = html;
return msg;

// Anti-spam: un email por congelador cada 10 minutos
var cong = msg.congelador || '?';
var key  = 'last_email_' + cong;
var last = global.get(key) || 0;
var now  = Date.now();
if (now - last < 600000) { return null; }
global.set(key, now);

msg.payload = {
    congelador: cong,
    alerta_tipo: msg.alerta_tipo || '',
    temperatura: msg.temp || null,
    especie: msg.esp || '',
    alerta_msg: msg.alerta_msg || ''
};
msg.headers = { 'Content-Type': 'application/json' };
msg.requestTimeout = 70000;
return msg;
